sys_ux_data_broker_transform.script:
function transform(input) {
    var scheduleSysId = input.scheduleSysId;
    var events = [];

    if (!scheduleSysId) {
        return { events: events };
    }

    var gr = new GlideRecord('cmn_schedule_span');
    gr.addQuery('schedule', scheduleSysId);
    gr.query();

    while (gr.next()) {
        var startDT = gr.getValue('start_date_time') || '';
        var endDT = gr.getValue('end_date_time') || '';

        events.push({
            sys_id: gr.getUniqueValue(),
            name: gr.getValue('name') || '',
            start: convertScheduleDateTime(startDT),
            end: convertScheduleDateTime(endDT),
            type: gr.getValue('type') || '',
            show_as: gr.getValue('show_as') || '',
            all_day: gr.getValue('all_day') === '1',
            linked_trip: gr.getValue('x_travel_buddy_app_u_linked_trip') || ''
        });
    }

    return { events: events };
}

function convertScheduleDateTime(sdt) {
    if (!sdt || sdt.length < 15) return '';
    // Input format: "20260827T054920" (yyyyMMddTHHmmss)
    // Output format: "2026-08-27 05:49:20" (yyyy-MM-dd HH:mm:ss)
    var year = sdt.substring(0, 4);
    var month = sdt.substring(4, 6);
    var day = sdt.substring(6, 8);
    // Position 8 is 'T' separator
    var hour = sdt.substring(9, 11);
    var min = sdt.substring(11, 13);
    var sec = sdt.substring(13, 15);
    return year + '-' + month + '-' + day + ' ' + hour + ':' + min + ':' + sec;
}
